+        private void BindMenu()
+        {
+            int? intDepartmentID = Variables.Url_DepartmentID;
+            if (intDepartmentID == null)
+                intDepartmentID = 0;
+            int intLanguageID = ResManager.CurrentLanguageID;
+            string strCacheKey = String.Format("HEADER_NEW_MENU_{0}_{1}", intDepartmentID.Value, intLanguageID);
+            dtbMenu = Cache[strCacheKey] as DataTable;
+            if (dtbMenu == null)
+            {
+                dtbMenu = new System_Menu().GetDataTable("System_Menu_SearchForWeb",
+                    "@DepartmentID", intDepartmentID,
+                    "@IsNotInMenuTree", 0,
+                    "@Parent", -1,
+                    "@LanguageID", intLanguageID);
+                if (dtbMenu != null)
+                    Cache.Insert(strCacheKey, dtbMenu, null, DateTime.Now.AddSeconds(10), Cache.NoSlidingExpiration);
+            }
+            litMenu.Text = String.Empty;
+            if (dtbMenu != null && dtbMenu.Rows.Count > 0)
+                litMenu.Text = GetMenuLevel("0");
+        }
+        private string GetMenuLevel(string strParentID)
+        {
+            string strMenu = String.Empty;
+            DataRow[] drwCurrentLevel = dtbMenu.Select("[Parent] = " + strParentID, "OrderIndex ASC");
+            for (int i = 0; i < drwCurrentLevel.Length; i++)
+            {
+                DataRow drw = drwCurrentLevel[i];
+                string strSub = GetMenuLevel(Convert.ToString(drw["MenuID"]));
+                string strLink = GenerateLink(Convert.ToString(drw["Link"]));
+                string strTitle = HttpUtility.HtmlEncode(Convert.ToString(drw["Description"]));
+                string strName = HttpUtility.HtmlEncode(Convert.ToString(drw["MenuName"]));
+                if (strSub == String.Empty)
+                    strMenu += String.Format("<li><a href=\"{0}\" title=\"{1}\">{2}</a></li>", strLink, strTitle, strName);
+                else
+                    strMenu += String.Format("<li class=\"dropdown\"><a href=\"{0}\" title=\"{1}\">{2}</a><ul class=\"shadow-box\">{3}</ul></li>", strLink, strTitle, strName, strSub);
+            }
+            return strMenu;
+        }
+        private string GenerateLink(string strLink)
+        {
+            strLink = (strLink ?? String.Empty).Trim();
+            if (strLink == String.Empty || strLink == "#")
+                return "#";
+            if (strLink.IndexOf("javascript:void(0)", StringComparison.OrdinalIgnoreCase) >= 0)
+                return strLink;
+            if (strLink.IndexOf("http://", StringComparison.OrdinalIgnoreCase) >= 0 || strLink.IndexOf("https://", StringComparison.OrdinalIgnoreCase) >= 0 || strLink.IndexOf("www.", StringComparison.OrdinalIgnoreCase) >= 0)
+                return strLink;
+            if (strLink.StartsWith("/", StringComparison.Ordinal))
+                return strLink;
+            return DCore.Globals.ApplicationVRoot + "/" + strLink;
         }
     }
 }
